{"path": "/app/bin/hourly.py", "content": "#!/usr/bin/env python3
"""Hourly station product from logger dumps (rules in /app/docs)."""
import json
import math
import os
import re
import sys
from datetime import datetime, timezone
from fractions import Fraction

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")
RANGES = {
    "temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
    "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000),
}
F = Fraction
CONV = {
    ("temp", "degC"): lambda v: v,
    ("temp", "degF"): lambda v: (v - 32) * 5 / 9,
    ("temp", "K"): lambda v: v - F("273.15"),
    ("rh", "pct"): lambda v: v,
    ("rh", "frac"): lambda v: v * 100,
    ("pres", "hPa"): lambda v: v,
    ("pres", "kPa"): lambda v: v * 10,
    ("pres", "inHg"): lambda v: v * F("33.8638866667"),
    ("pres", "mmHg"): lambda v: v * F("1.33322387415"),
    ("wspd", "ms"): lambda v: v,
    ("wspd", "kmh"): lambda v: v / F("3.6"),
    ("wspd", "kn"): lambda v: v * 1852 / 3600,
    ("wspd", "mph"): lambda v: v * F("0.44704"),
    ("wdir", "deg"): lambda v: v,
    ("rain", "mm"): lambda v: v,
}

DIRECTIVE = re.compile(r"^#[ ]*([a-z]+)[ ]*:(.*)$")
MISSING9999 = re.compile(r"^-9999(\.0*)?$")
EPOCH = datetime(1970, 1, 1)


def parse_time(s):
    s = s.strip().replace("T", " ")
    return int((datetime.strptime(s, "%Y-%m-%d %H:%M:%S") - EPOCH).total_seconds())


def parse_tz(s):
    s = s.strip()
    if s == "Z":
        return 0
    sign = -1 if s[0] == "-" else 1
    hh, mm = s[1:].split(":")
    return sign * (int(hh) * 3600 + int(mm) * 60)


def parse_ref(s):
    s = s.strip()
    return parse_time(s[:-1] if s.endswith("Z") else s)


def converter(q, unit):
    if (q, unit) in CONV:
        return CONV[(q, unit)]
    if q == "rain" and unit.startswith("tips:"):
        try:
            s = F(unit[5:])
        except (ValueError, ZeroDivisionError):
            return None
        return lambda v: v * s
    return None


def parse_value(q, text, unit):
    t = text.strip()
    if t == "" or t == "---" or t.lower() == "nan" or MISSING9999.match(t):
        return None
    try:
        v = F(t)
    except (ValueError, ZeroDivisionError):
        return None
    conv = converter(q, unit)
    if conv is None:
        return None
    v = conv(v)
    lo, hi = RANGES[q]
    if v < lo or v > hi:
        return None
    return v


def read_dump(path):
    with open(path, "rb") as fh:
        text = fh.read().decode("utf-8-sig")
    hdr = {}
    columns = None
    units = {}
    rows = []   # (logger_time, {q: value})
    syncs = []  # (logger_time, ref)
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if line.strip() == "":
            continue
        if line[0] == "#":
            m = DIRECTIVE.match(line)
            if not m:
                continue
            key, val = m.group(1), m.group(2).strip()
            if key in ("station", "upload", "interval", "tz"):
                hdr[key] = val
            elif key == "columns":
                columns = [c.strip() for c in val.split(",")]
            elif key == "units":
                for pair in val.split():
                    if "=" in pair:
                        k, u = pair.split("=", 1)
                        units[k] = u
            elif key == "sync":
                lg = rf = None
                for part in val.split():
                    if part.startswith("logger="):
                        lg = part[7:]
                    elif part.startswith("ref="):
                        rf = part[4:]
                if lg is None:
                    mm = re.search(r"logger=(\S+ \S+)", val)
                    lg = mm.group(1) if mm else None
                if lg is not None and rf is not None:
                    syncs.append((parse_time(lg), parse_ref(rf)))
            continue
        if columns is None:
            continue
        fields = line.split(",")
        row = {}
        ltime = None
        for name, f in zip(columns, fields):
            if name == "time":
                ltime = parse_time(f)
            elif name in RANGES:
                row[name] = parse_value(name, f, units.get(name, _canon(name)))
        if ltime is not None:
            rows.append((ltime, row))
    return hdr, rows, syncs


def _canon(q):
    return {"temp": "degC", "rh": "pct", "pres": "hPa", "wspd": "ms",
            "wdir": "deg", "rain": "mm"}[q]


def offset_at(points, t):
    # points: sorted list of (t, offset)
    if not points:
        return 0
    if t <= points[0][0]:
        return points[0][1]
    if t >= points[-1][0]:
        return points[-1][1]
    lo, hi = 0, len(points) - 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if points[mid][0] <= t:
            lo = mid
        else:
            hi = mid
    t1, o1 = points[lo]
    t2, o2 = points[hi]
    if t == t1:
        return o1
    return (o1 * (t2 - t1) + (o2 - o1) * (t - t1)) // (t2 - t1)


def hour_end(c):
    return -((-c) // 3600) * 3600


def fmt_hour(e):
    return datetime.fromtimestamp(e, timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")


def rnd(x):
    r = round(x, 2) + 0.0
    return r


def main(indir, outfile):
    stations = {}
    names = sorted(n for n in os.listdir(indir)
                   if n.endswith(".log") and os.path.isfile(os.path.join(indir, n)))
    for n in names:
        hdr, rows, syncs = read_dump(os.path.join(indir, n))
        if "station" not in hdr:
            continue
        sid = hdr["station"]
        st = stations.setdefault(sid, {"interval": None, "samples": {}, "syncs": {}, "rows": 0})
        upload = int(hdr.get("upload", "0"))
        if "interval" in hdr and st["interval"] is None:
            st["interval"] = int(hdr["interval"])
        tz = parse_tz(hdr.get("tz", "Z"))
        for lt, rf in syncs:
            inst = lt - tz
            old = st["syncs"].get(inst)
            if old is None or upload > old[0]:
                st["syncs"][inst] = (upload, rf - inst)
        for lt, row in rows:
            inst = lt - tz
            old = st["samples"].get(inst)
            if old is None or upload > old[0]:
                st["samples"][inst] = (upload, row)

    out = {"stations": []}
    for sid in sorted(stations):
        st = stations[sid]
        if not st["samples"]:
            continue
        interval = st["interval"]
        expected = 3600 // interval
        points = sorted((t, o) for t, (_, o) in st["syncs"].items())
        recs = []
        for inst, (_, row) in st["samples"].items():
            recs.append((inst + offset_at(points, inst), inst, row))
        recs.sort(key=lambda r: (r[0], r[1]))
        first = hour_end(recs[0][0])
        last = hour_end(recs[-1][0])
        acc = {}

        def cell(h):
            return acc.setdefault(h, {q: {"n": 0, "sum": 0, "vx": 0.0, "vy": 0.0, "nv": 0}
                                      for q in QUANTITIES})

        prev_rain = None
        for c, inst, row in recs:
            h = hour_end(c)
            a = None
            for q in QUANTITIES:
                v = row.get(q)
                if v is None:
                    continue
                if a is None:
                    a = cell(h)
                e = a[q]
                e["n"] += 1
                if q == "rain":
                    if prev_rain is not None and (c - prev_rain[0]) * 2 <= 5 * interval:
                        p = prev_rain[1]
                        e["sum"] += (v - p) if v >= p else v
                    prev_rain = (c, v)
                elif q == "wdir":
                    w = row.get("wspd")
                    if w is not None and w > 0:
                        ang = math.radians(float(v))
                        e["vx"] += math.sin(ang)
                        e["vy"] += math.cos(ang)
                        e["nv"] += 1
                else:
                    e["sum"] += v
        hours = []
        for he in range(first, last + 3600, 3600):
            a = acc.get(he)
            entry = {"hour": fmt_hour(he)}
            for q in QUANTITIES:
                if a is None:
                    entry[q] = {"value": None, "n": 0}
                    continue
                e = a[q]
                n = e["n"]
                val = None
                if n * 4 >= expected * 3 and n > 0:
                    if q == "wdir":
                        if e["nv"] > 0 and (e["vx"] != 0.0 or e["vy"] != 0.0):
                            d = math.degrees(math.atan2(e["vx"], e["vy"])) % 360
                            d = rnd(d)
                            if d >= 360:
                                d = 0.0
                            val = d
                    elif q == "rain":
                        val = rnd(float(e["sum"]))
                    else:
                        val = rnd(float(e["sum"] / n))
                entry[q] = {"value": val, "n": n}
            hours.append(entry)
        out["stations"].append({"station": sid, "interval_s": interval, "hours": hours})

    d = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(d, exist_ok=True)
    with open(outfile, "w", encoding="utf-8") as fh:
        json.dump(out, fh, indent=1)
        fh.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
"}
